from fastapi import FastAPI

app = FastAPI()
products = [{"name": "Veste", "stock": 3}, {"name": "Sac", "stock": 0}]

@app.get("/catalog-summary")
def catalog_summary():
    return {
        "products": len(products),
        "in_stock": sum(1 for product in products if product["stock"] > 0),
    }

export async function GET() {
  const base = process.env.PYTHON_API_URL || "http://127.0.0.1:8000";
  try {
    const response = await fetch(new URL("/catalog-summary", base), {
      cache: "no-store", signal: AbortSignal.timeout(5000),
    });
    if (!response.ok) throw new Error("Python unavailable");
    const data = await response.json();
    if (!data || !Number.isInteger(data.products) ||
        !Number.isInteger(data.in_stock) || data.products < 0 ||
        data.in_stock < 0 || data.in_stock > data.products) {
      throw new Error("Invalid response");
    }
    return Response.json({ products: data.products, in_stock: data.in_stock });
  } catch {
    return Response.json({ error: "Service Python indisponible" }, { status: 503 });
  }
}

"use client";
import { useState } from "react";
export default function PythonDemo() {
  const [message, setMessage] = useState("Prêt à charger");
  const [loading, setLoading] = useState(false);
  async function load() {
    setLoading(true);
    setMessage("Chargement…");
    try {
      const response = await fetch("/api/python-demo", {
        signal: AbortSignal.timeout(10000), cache: "no-store",
      });
      if (!response.ok) throw new Error("Service unavailable");
      const data = await response.json();
      if (!data || !Number.isInteger(data.products) ||
          !Number.isInteger(data.in_stock)) throw new Error("Invalid data");
      setMessage(`${data.products} produits ; ${data.in_stock} en stock`);
    } catch { setMessage("Service indisponible. Réessaie."); }
    finally { setLoading(false); }
  }
  return <main><h1>Mon atelier Python</h1>
    <button disabled={loading} onClick={load}>Charger</button>
    <p role="status">{message}</p>
  </main>;
}

from pydantic import BaseModel, Field

class DemoCart(BaseModel):
    price_cents: int = Field(ge=0, le=1000000, strict=True)
    quantity: int = Field(ge=1, le=100, strict=True)

@app.post("/demo-total")
def demo_total(cart: DemoCart):
    return {"total_cents": cart.price_cents * cart.quantity}

from fastapi.testclient import TestClient
from main import app

client = TestClient(app)

def test_total():
    response = client.post("/demo-total", json={"price_cents": 19900, "quantity": 2})
    assert response.status_code == 200
    assert response.json() == {"total_cents": 39800}

def test_reject_negative_quantity():
    response = client.post("/demo-total", json={"price_cents": 19900, "quantity": -1})
    assert response.status_code == 422

def count_available(products: list[dict]) -> int:
